import math
import string


M = 26
ALPHABET = string.ascii_lowercase


def _check_coprime(a, m=M):
    if math.gcd(a, m) != 1:
        raise ValueError("a and m must be coprime.")


def _modinv(a, m=M):
    # Extended Euclidean Algorithm to find modular inverse of a mod m
    # assumes gcd(a, m) == 1
    a = a % m
    # Use built-in if available and convenient
    try:
        return pow(a, -1, m)
    except TypeError:
        # Fallback implementation
        t, newt = 0, 1
        r, newr = m, a
        while newr != 0:
            q = r // newr
            t, newt = newt, t - q * newt
            r, newr = newr, r - q * newr
        if r > 1:
            raise ValueError("a and m must be coprime.")
        if t < 0:
            t += m
        return t


def _clean_text_for_encode(text):
    # Keep letters and digits; drop others. Lowercase letters.
    cleaned = []
    for ch in text.lower():
        if ch.isalpha():
            cleaned.append(ch)
        elif ch.isdigit():
            cleaned.append(ch)
        # else drop
    return ''.join(cleaned)


def _clean_text_for_decode(text):
    # Remove spaces and punctuation; keep letters and digits; lowercase letters.
    cleaned = []
    for ch in text.lower():
        if ch.isalpha() or ch.isdigit():
            cleaned.append(ch)
    return ''.join(cleaned)


def _encode_char(ch, a, b):
    if ch.isalpha():
        i = ord(ch) - ord('a')
        e = (a * i + b) % M
        return ALPHABET[e]
    else:
        # digits are not encrypted
        return ch


def _decode_char(ch, a_inv, b):
    if ch.isalpha():
        y = ord(ch) - ord('a')
        d = (a_inv * (y - b)) % M
        return ALPHABET[d]
    else:
        return ch


def encode(plain_text, a, b):
    """
    Encode plain_text using affine cipher with keys a and b.
    Raises ValueError if a and 26 are not coprime.
    """
    _check_coprime(a, M)

    cleaned = _clean_text_for_encode(plain_text)
    transformed = [_encode_char(ch, a, b) for ch in cleaned]

    # Group into chunks of 5 characters
    groups = []
    for i in range(0, len(transformed), 5):
        groups.append(''.join(transformed[i:i + 5]))
    return ' '.join(groups)


def decode(ciphered_text, a, b):
    """
    Decode ciphered_text using affine cipher with keys a and b.
    Raises ValueError if a and 26 are not coprime.
    """
    _check_coprime(a, M)

    cleaned = _clean_text_for_decode(ciphered_text)
    a_inv = _modinv(a, M)

    transformed = [_decode_char(ch, a_inv, b) for ch in cleaned]
    return ''.join(transformed)
